// Internal component -- not exported from @arvo/react public API.
// Used inside ArvoSidePanel and ArvoDrawer to render the shared panel interior.
//
// Composes Arvo primitives: ArvoIconButton (back/close), one of
// ArvoIconButton/ArvoDropdownIconButton/ArvoSplitIconButton/ArvoSwitch/
// ArvoCheckbox per header-action type, ArvoTabstrip, ArvoSearch, ArvoButton
// (footer + Clear Search), ArvoBannerAlert in the sticky `__banner` slot,
// and ArvoMessageAlert in the sticky `__info` slot.

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { useControllableState } from '../../hooks/useControllableState';
import { createTabRoving, type TabRoving, type ListItemBase } from '@arvo/core';
import {
  runItemFilter,
  formatMatchCountMessage,
  validateHeaderAction,
  type ArvoPanelHeaderAction,
  type ArvoPanelHeaderActionDropdown,
  type ArvoPanelHeaderActionSplit,
  type ArvoPanelStickyHeaderConfig,
  type ArvoPanelInfoConfig,
  type ArvoPanelTabConfig,
  type ArvoPanelAction,
  type ArvoPanelDefaultItem,
} from '@arvo/utils';

import ArvoIconButton from '../IconButton/IconButton';
import ArvoDropdownIconButton from '../DropdownIconButton/DropdownIconButton';
import ArvoSplitIconButton from '../SplitIconButton/SplitIconButton';
import ArvoSwitch from '../Switch/Switch';
import ArvoCheckbox from '../Checkbox/Checkbox';
import ArvoTabstrip, { type TabItem } from '../Tabstrip/Tabstrip';
import ArvoSearch from '../Search/Search';
import ArvoButton from '../Button/Button';
import { ArvoBannerAlert } from '../BannerAlert/BannerAlert';
import {
  ArvoMessageAlert,
  type ArvoMessageAlertType,
} from '../MessageAlert/MessageAlert';
import type { MenuItemData } from '../ActionMenu/ActionMenu';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface PanelShellProps<T extends ListItemBase = ListItemBase> {
  parentBlock: string;
  pinSlot?: ReactNode;

  title?: string | null;
  hasHeader?: boolean;
  hasBackButton?: boolean;
  onBack?: () => void;
  headerActions?: ArvoPanelHeaderAction[];
  stickyHeader?: ArvoPanelStickyHeaderConfig | false;

  items?: T[];
  getItemId?: (item: T) => string;
  filterKeys?: Array<keyof T & string>;
  getItemSearchText?: (item: T) => string;
  renderItem?: (item: T) => ReactNode;
  itemsRole?: 'listbox' | 'list' | 'menu';

  actions?: ArvoPanelAction[] | false;
  hasFooter?: boolean;
  isClosable?: boolean;
  onClose?: () => void;

  isLoading?: boolean;
  isDisabled?: boolean;

  isPinnableCount?: number;
  isClosableCount?: number;

  children?: ReactNode;
  className?: string;

  /** Controlled search query. */
  searchQuery?: string;
  /** Default search query for uncontrolled mode. */
  defaultSearchQuery?: string;
  onSearchChange?: (query: string, matchedCount: number | null) => void;
  onItemActivate?: (id: string, item: T) => void;
  onTabSelect?: (id: string) => void;
}

export interface PanelShellHandle {
  setItems(items: ListItemBase[]): void;
  setStickyHeader(config: ArvoPanelStickyHeaderConfig | false): void;
  setHeaderActions(actions: ArvoPanelHeaderAction[]): void;
  setActions(actions: ArvoPanelAction[] | false): void;
  updateAction(id: string, patch: Partial<ArvoPanelHeaderAction | ArvoPanelAction>): void;
  search(query?: string): string | void;
  selectedTab(id?: string): string | null | void;
  setTitle(title: string | null): void;
  loading(state?: boolean): boolean | void;
  disabled(state?: boolean): boolean | void;
  focus(target?: 'first' | 'title' | 'search' | 'list'): void;
}

// ---------------------------------------------------------------------------
// HeaderAction subcomponent -- composes the appropriate Arvo primitive
// ---------------------------------------------------------------------------

interface HeaderActionProps {
  action: ArvoPanelHeaderAction;
  block: string;
  isDisabled?: boolean;
}

export function HeaderAction({ action, block, isDisabled }: HeaderActionProps) {
  if (!validateHeaderAction(action)) return null;

  const baseClass = `${block}__action`;

  // All header actions are forced to size=sm + variant=tertiary regardless of
  // any consumer override (per the panel-shell-header-action SCSS contract).
  switch (action.type) {
    case 'btn': {
      const tooltip = action.tooltip ?? action.label ?? action.id;
      return (
        <div
          className={baseClass}
          data-action-id={action.id}
          data-action-type={action.type}
        >
          <ArvoIconButton
            size="sm"
            variant="tertiary"
            icon={action.icon}
            tooltip={tooltip}
            isDisabled={isDisabled || action.isDisabled}
            isLoading={action.isLoading}
            isSelected={action.isSelected}
            onClick={() => {
              if (isDisabled || action.isDisabled) return;
              action.onClick?.();
            }}
          />
        </div>
      );
    }

    case 'dropdown': {
      const dd = action as ArvoPanelHeaderActionDropdown;
      const tooltip = dd.tooltip ?? dd.label ?? dd.id;
      return (
        <div
          className={baseClass}
          data-action-id={dd.id}
          data-action-type={dd.type}
        >
          <ArvoDropdownIconButton
            size="sm"
            variant="tertiary"
            icon={dd.icon}
            tooltip={tooltip}
            items={dd.items as MenuItemData[]}
            placement={dd.placement ?? 'bottom-end'}
            isDisabled={isDisabled || dd.isDisabled}
            isLoading={dd.isLoading}
            onSelect={(item) => {
              if (isDisabled || dd.isDisabled) return;
              dd.onSelect?.(item.id);
            }}
          />
        </div>
      );
    }

    case 'split': {
      const sp = action as ArvoPanelHeaderActionSplit;
      const tooltip = sp.tooltip ?? sp.label ?? sp.id;
      return (
        <div
          className={baseClass}
          data-action-id={sp.id}
          data-action-type={sp.type}
        >
          <ArvoSplitIconButton
            size="sm"
            variant="tertiary"
            icon={sp.icon}
            tooltip={tooltip}
            triggerLabel={sp.triggerLabel}
            items={sp.items as MenuItemData[]}
            placement={sp.placement ?? 'bottom-end'}
            isDisabled={isDisabled || sp.isDisabled}
            isActionDisabled={sp.isActionDisabled}
            isTriggerDisabled={sp.isTriggerDisabled}
            isLoading={sp.isLoading}
            onAction={() => {
              if (isDisabled || sp.isDisabled) return;
              sp.onClick?.();
            }}
            onSelect={(item) => {
              if (isDisabled || sp.isDisabled) return;
              sp.onSelect?.(item.id);
            }}
          />
        </div>
      );
    }

    case 'switch':
      return (
        <div
          className={baseClass}
          data-action-id={action.id}
          data-action-type={action.type}
          aria-label={action.label}
        >
          <ArvoSwitch
            isChecked={action.isChecked}
            defaultChecked={action.defaultChecked}
            isDisabled={isDisabled || action.isDisabled}
            isReadOnly={action.isReadOnly}
            isLoading={action.isLoading}
            aria-label={action.label}
            onChange={({ isChecked }) => {
              if (isDisabled || action.isDisabled) return;
              action.onChange?.(isChecked);
            }}
          />
        </div>
      );

    case 'checkbox':
      return (
        <div
          className={baseClass}
          data-action-id={action.id}
          data-action-type={action.type}
          aria-label={action.label}
        >
          <ArvoCheckbox
            size="sm"
            isChecked={action.isChecked}
            defaultChecked={action.defaultChecked}
            isIndeterminate={action.isIndeterminate}
            isDisabled={isDisabled || action.isDisabled}
            isReadOnly={action.isReadOnly}
            isLoading={action.isLoading}
            aria-label={action.label}
            onChange={({ isChecked }) => {
              if (isDisabled || action.isDisabled) return;
              action.onChange?.(isChecked);
            }}
          />
        </div>
      );
  }
}

// ---------------------------------------------------------------------------
// PanelInfo -- private helper that renders an ArvoMessageAlert inside the
// `__info` slot. NOT exported from @arvo/react. The `__info` wrapper stays
// parent-block-scoped (`{block}__info`); the inner DOM is owned by
// ArvoMessageAlert. Role is auto-resolved from the type (error|warning|block
// -> alert; info|success|neutral -> status) so panel-shell announces the
// info content with the same model as inline form-field errors.
// ---------------------------------------------------------------------------

interface PanelInfoProps {
  config: ArvoPanelInfoConfig;
  message: string;
  block: string;
}

function resolvePanelInfoRole(
  type: ArvoMessageAlertType,
): 'alert' | 'status' {
  return type === 'error' || type === 'warning' || type === 'block'
    ? 'alert'
    : 'status';
}

function PanelInfo({ config, message, block }: PanelInfoProps) {
  const type = (config.type ?? 'info') as ArvoMessageAlertType;
  const role = resolvePanelInfoRole(type);
  return (
    <div className={`${block}__info`}>
      <ArvoMessageAlert type={type} role={role} message={message} />
    </div>
  );
}

// ---------------------------------------------------------------------------
// Skeleton rows
// ---------------------------------------------------------------------------

function SkeletonRows({ block }: { block: string }) {
  const widths = ['wide', 'medium', 'narrow', 'wide', 'medium'] as const;
  return (
    <div className={`${block}__skeleton`}>
      {widths.map((w, i) => (
        <div key={i} className={`${block}__skeleton__row ${block}__skeleton__row--${w}`} />
      ))}
    </div>
  );
}

// ---------------------------------------------------------------------------
// EmptyState
// ---------------------------------------------------------------------------

interface EmptyStateProps {
  block: string;
  variant: 'no-data' | 'no-results';
  onClearSearch?: () => void;
}

function EmptyState({ block, variant, onClearSearch }: EmptyStateProps) {
  return (
    <div className={`${block}__empty`}>
      <div className={`${block}__empty-illus`} aria-hidden="true" />
      <div className={`${block}__empty-title`}>
        {variant === 'no-data' ? 'No data' : 'No results found'}
      </div>
      <div className={`${block}__empty-msg`}>
        {variant === 'no-data'
          ? 'There are no items to display.'
          : 'Try adjusting your search terms.'}
      </div>
      {variant === 'no-results' && onClearSearch && (
        <div className={`${block}__empty-action`}>
          <ArvoButton
            variant="outline"
            size="sm"
            label="Clear search"
            onClick={onClearSearch}
          />
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Default item template -- emits the shared list-item DOM contract inside
// the `__item` host element. Reads optional fields on the item:
//   - avatarUrl  -> `<img class="{block}__item__avatar" />` (wins over icon)
//   - icon       -> `<i class="o9con-{name} {block}__item__ico" />`
//   - label      -> `<span class="{block}__item__lbl">`
//   - secondaryLabel (or `description` alias) -> `<span class="{block}__item__secondary">`
// `isActive` / `isDisabled` are applied to the host `__item` row (not here).
// ---------------------------------------------------------------------------

function renderDefaultItem(
  item: ArvoPanelDefaultItem,
  block: string,
): ReactNode {
  const secondary = item.secondaryLabel ?? item.description;
  const hasAvatar = !!item.avatarUrl;
  const hasIcon = !hasAvatar && !!item.icon;
  return (
    <>
      {hasAvatar && (
        <img
          className={`${block}__item__avatar`}
          src={item.avatarUrl}
          alt=""
        />
      )}
      {hasIcon && (
        <i
          className={`o9con-${item.icon} ${block}__item__ico`}
          aria-hidden="true"
        />
      )}
      <div className={`${block}__item__txt`}>
        <span className={`${block}__item__lbl`}>{item.label}</span>
        {secondary && (
          <span className={`${block}__item__secondary`}>{secondary}</span>
        )}
      </div>
    </>
  );
}

// ---------------------------------------------------------------------------
// PanelShell
// ---------------------------------------------------------------------------

function PanelShellInner<T extends ListItemBase = ListItemBase>(
  props: PanelShellProps<T>,
  ref: React.ForwardedRef<PanelShellHandle>,
) {
  const {
    parentBlock: block,
    pinSlot,
    title: titleProp,
    hasHeader = true,
    hasBackButton = false,
    onBack,
    headerActions: headerActionsProp,
    stickyHeader: stickyHeaderProp = false,
    items: itemsProp,
    getItemId = (item: T) => (item as ListItemBase).id,
    filterKeys,
    getItemSearchText,
    renderItem,
    itemsRole = 'list',
    actions: actionsProp = false,
    isClosable = false,
    onClose,
    isLoading: isLoadingProp = false,
    isDisabled: isDisabledProp = false,
    isPinnableCount = 0,
    isClosableCount,
    children,
    className,
    searchQuery: searchQueryProp,
    defaultSearchQuery = '',
    onSearchChange,
    onItemActivate,
    onTabSelect,
  } = props;

  // -- Internal state mirrors props but is also writable via the imperative
  // handle (setItems/setStickyHeader/setHeaderActions/setActions/updateAction/
  // setTitle/loading/disabled). When props change, mirror them in.
  const [titleState, setTitleState] = useState<string | null>(titleProp ?? null);
  const [headerActionsState, setHeaderActionsState] =
    useState<ArvoPanelHeaderAction[]>(headerActionsProp ?? []);
  const [stickyState, setStickyState] =
    useState<ArvoPanelStickyHeaderConfig | false>(stickyHeaderProp);
  const [actionsState, setActionsState] =
    useState<ArvoPanelAction[] | false>(actionsProp);
  const [itemsState, setItemsState] = useState<T[] | undefined>(itemsProp);
  const [loadingState, setLoadingState] = useState<boolean>(isLoadingProp);
  const [disabledState, setDisabledState] = useState<boolean>(isDisabledProp);

  useEffect(() => { setTitleState(titleProp ?? null); }, [titleProp]);
  useEffect(() => { setHeaderActionsState(headerActionsProp ?? []); }, [headerActionsProp]);
  useEffect(() => { setStickyState(stickyHeaderProp); }, [stickyHeaderProp]);
  useEffect(() => { setActionsState(actionsProp); }, [actionsProp]);
  useEffect(() => { setItemsState(itemsProp); }, [itemsProp]);
  useEffect(() => { setLoadingState(isLoadingProp); }, [isLoadingProp]);
  useEffect(() => { setDisabledState(isDisabledProp); }, [isDisabledProp]);

  const [searchQuery, setSearchQuery] = useControllableState(
    searchQueryProp,
    defaultSearchQuery,
  );
  const [selectedTabId, setSelectedTabId] = useControllableState<string | null>(
    undefined,
    null,
  );

  const listRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLDivElement>(null);
  const titleRef = useRef<HTMLSpanElement>(null);
  const tabRovingRef = useRef<TabRoving | null>(null);

  const titleId = useMemo(
    () => `${block}-title-${Math.random().toString(36).slice(2, 9)}`,
    [block],
  );

  // -- Items + children conflict warning -----------------------------------
  useEffect(() => {
    if (
      itemsState !== undefined &&
      children &&
      typeof process !== 'undefined' &&
      process.env.NODE_ENV !== 'production'
    ) {
      console.warn(
        `[PanelShell] Both "items" and "children" were provided. ` +
        `When "items" is set, "children" is ignored.`,
      );
    }
  }, [itemsState, children]);

  // -- Header-action cap warning -------------------------------------------
  const closableCount = isClosableCount ?? (isClosable ? 1 : 0);
  const validActionCount = useMemo(
    () => headerActionsState.filter((a) => validateHeaderAction(a)).length,
    [headerActionsState],
  );

  useEffect(() => {
    const total = validActionCount + isPinnableCount + closableCount;
    if (
      total > 4 &&
      typeof process !== 'undefined' &&
      process.env.NODE_ENV !== 'production'
    ) {
      console.warn(
        `[PanelShell] Total header actions (${total}) exceeds cap of 4. ` +
        `Computed across headerActions (${validActionCount}) + isPinnable (${isPinnableCount}) + isClosable (${closableCount}).`,
      );
    }
  }, [validActionCount, isPinnableCount, closableCount]);

  // -- Filter pipeline -----------------------------------------------------
  const hasItems = itemsState !== undefined;

  const filteredItems = useMemo(() => {
    if (itemsState === undefined) return [];
    if (!searchQuery) return itemsState;
    return runItemFilter(itemsState, searchQuery, {
      keys: filterKeys,
      getItemSearchText,
    });
  }, [itemsState, searchQuery, filterKeys, getItemSearchText]);

  const emptyState: 'no-data' | 'no-results' | null = useMemo(() => {
    if (!hasItems) return null;
    if (itemsState!.length === 0) return 'no-data';
    if (filteredItems.length === 0 && searchQuery) return 'no-results';
    return null;
  }, [hasItems, itemsState, filteredItems, searchQuery]);

  // -- Roving tabindex on list ---------------------------------------------
  useEffect(() => {
    if (!listRef.current || !hasItems || loadingState) return;

    const itemEls = Array.from(
      listRef.current.querySelectorAll<HTMLElement>(`.${block}__item`),
    );
    if (itemEls.length === 0) return;

    const roving = createTabRoving();
    roving.activate({
      container: listRef.current,
      items: itemEls,
      orientation: 'vertical',
      wrap: true,
    });
    tabRovingRef.current = roving;

    return () => {
      roving.deactivate();
      tabRovingRef.current = null;
    };
  }, [block, hasItems, filteredItems, loadingState]);

  // -- Search handlers -----------------------------------------------------
  const handleSearchChange = useCallback(
    (value: string) => {
      setSearchQuery(value);
      if (hasItems) {
        const matched = runItemFilter(itemsState!, value, {
          keys: filterKeys,
          getItemSearchText,
        });
        onSearchChange?.(value, matched.length);
      } else {
        onSearchChange?.(value, null);
      }
    },
    [setSearchQuery, hasItems, itemsState, filterKeys, getItemSearchText, onSearchChange],
  );

  const handleClearSearch = useCallback(() => {
    setSearchQuery('');
    onSearchChange?.('', itemsState?.length ?? 0);
    // ArvoSearch root element exposes the input internally; we focus the
    // search root and let it route focus to its inner input.
    const inputEl = searchRef.current?.querySelector<HTMLElement>(
      'input, textarea',
    );
    inputEl?.focus();
  }, [setSearchQuery, onSearchChange, itemsState]);

  // -- Sticky config + computed info message -------------------------------
  const stickyConfig = stickyState ? stickyState : null;

  const infoMessage = useMemo(() => {
    if (!stickyConfig?.info) return null;
    const infoCfg = stickyConfig.info;
    if (infoCfg.showMatchCount && hasItems) {
      return formatMatchCountMessage(filteredItems.length, infoCfg.matchCountTemplate);
    }
    return infoCfg.message ?? null;
  }, [stickyConfig, hasItems, filteredItems]);

  // -- Tabstrip wiring -----------------------------------------------------
  const tabsForTabstrip: TabItem[] = useMemo(() => {
    if (!stickyConfig?.tabs) return [];
    return stickyConfig.tabs.map((t: ArvoPanelTabConfig) => ({
      id: t.id,
      label: t.label,
      icon: t.icon,
      isDisabled: t.isDisabled,
    }));
  }, [stickyConfig]);

  // Resolve initial tab if none set yet.
  useEffect(() => {
    if (!stickyConfig?.tabs?.length) return;
    if (selectedTabId !== null) return;
    const first = stickyConfig.tabs.find((t) => !t.isDisabled);
    if (first) setSelectedTabId(first.id);
  }, [stickyConfig, selectedTabId, setSelectedTabId]);

  // -- Search counter ------------------------------------------------------
  const searchCounter = useMemo<{ current: number; total: number } | null>(() => {
    if (!stickyConfig?.search) return null;
    if (typeof stickyConfig.search !== 'object') return null;
    if (!stickyConfig.search.showCounter) return null;
    if (!hasItems) return null;
    return { current: filteredItems.length, total: itemsState!.length };
  }, [stickyConfig, hasItems, filteredItems, itemsState]);

  const searchPlaceholder = useMemo(() => {
    if (!stickyConfig?.search || typeof stickyConfig.search !== 'object') return 'Search';
    return stickyConfig.search.placeholder ?? 'Search';
  }, [stickyConfig]);

  const searchShortcut = useMemo(() => {
    if (!stickyConfig?.search || typeof stickyConfig.search !== 'object') return undefined;
    return stickyConfig.search.shortcut;
  }, [stickyConfig]);

  // -- Host classes --------------------------------------------------------
  const hostClasses = useMemo(() => {
    const cls: string[] = [];
    if (loadingState) cls.push('loading');
    if (disabledState) cls.push('is-disabled');
    if (emptyState === 'no-data') cls.push('no-data');
    if (emptyState === 'no-results') cls.push('no-results');
    if (stickyConfig?.banner) cls.push(`${block}--with-banner`);
    if (stickyConfig?.tabs && stickyConfig.tabs.length > 0) cls.push(`${block}--with-tabs`);
    if (stickyConfig?.search) cls.push(`${block}--with-search`);
    if (stickyConfig?.info) cls.push(`${block}--with-info`);
    if (actionsState && actionsState.length > 0) cls.push(`${block}--with-footer`);
    if (className) cls.push(className);
    return cls.join(' ');
  }, [block, loadingState, disabledState, emptyState, stickyConfig, actionsState, className]);

  // -- Imperative handle ---------------------------------------------------
  useImperativeHandle(ref, () => ({
    setItems(next) {
      setItemsState(next as unknown as T[]);
    },
    setStickyHeader(config) {
      setStickyState(config);
    },
    setHeaderActions(next) {
      setHeaderActionsState(next);
    },
    setActions(next) {
      setActionsState(next);
    },
    updateAction(id, patch) {
      setHeaderActionsState((prev) => {
        const idx = prev.findIndex((a) => a.id === id);
        if (idx >= 0) {
          const next = [...prev];
          next[idx] = { ...next[idx], ...patch } as ArvoPanelHeaderAction;
          return next;
        }
        return prev;
      });
      setActionsState((prev) => {
        if (!prev) return prev;
        const idx = prev.findIndex((a) => a.id === id);
        if (idx >= 0) {
          const next = [...prev];
          next[idx] = { ...next[idx], ...patch } as ArvoPanelAction;
          return next;
        }
        return prev;
      });
    },
    search(query?: string): string | void {
      if (query === undefined) return searchQuery;
      setSearchQuery(query);
    },
    selectedTab(id?: string): string | null | void {
      if (id === undefined) return selectedTabId;
      setSelectedTabId(id);
    },
    setTitle(next) {
      setTitleState(next);
    },
    loading(state?: boolean): boolean | void {
      if (state === undefined) return loadingState;
      setLoadingState(state);
    },
    disabled(state?: boolean): boolean | void {
      if (state === undefined) return disabledState;
      setDisabledState(state);
    },
    focus(target?: 'first' | 'title' | 'search' | 'list'): void {
      const t = target ?? 'first';
      if (t === 'search' && searchRef.current) {
        const input = searchRef.current.querySelector<HTMLElement>('input, textarea');
        input?.focus();
        return;
      }
      if (t === 'title' && titleRef.current) {
        titleRef.current.setAttribute('tabindex', '-1');
        titleRef.current.focus();
        return;
      }
      if (t === 'list' && listRef.current) {
        const first = listRef.current.querySelector<HTMLElement>(`.${block}__item`);
        if (first) {
          first.focus();
          tabRovingRef.current?.setActiveItem(0);
        }
        return;
      }
      // 'first'
      if (searchRef.current) {
        const input = searchRef.current.querySelector<HTMLElement>('input, textarea');
        if (input) { input.focus(); return; }
      }
      if (titleRef.current) {
        titleRef.current.setAttribute('tabindex', '-1');
        titleRef.current.focus();
      }
    },
  }), [block, searchQuery, selectedTabId, loadingState, disabledState, setSearchQuery, setSelectedTabId]);

  // -- Render --------------------------------------------------------------
  // The wrapper participates in the flex-column layout chain established by
  // `{block}__pane`. Without it the body cannot grow (overflow scroll) and
  // the footer cannot pin to the bottom -- the bug C8 in phase1-review.md.
  const wrapperClasses = ['arvo-panel-shell', hostClasses].filter(Boolean).join(' ');

  return (
    <div className={wrapperClasses} aria-busy={loadingState || undefined}>
      {/* Header */}
      {hasHeader && (
        <div className={`${block}__hdr`}>
          <div className={`${block}__hdr-lft`}>
            {hasBackButton && (
              <ArvoIconButton
                className={`${block}__back`}
                size="sm"
                variant="tertiary"
                icon="arrow-left"
                tooltip="Back"
                isDisabled={disabledState}
                onClick={() => { if (!disabledState) onBack?.(); }}
              />
            )}
            <span
              ref={titleRef}
              id={titleId}
              className={`${block}__title`}
            >
              {titleState}
            </span>
          </div>
          <div className={`${block}__hdr-actions`}>
            {headerActionsState
              .filter((a) => validateHeaderAction(a))
              .map((action) => (
                <HeaderAction
                  key={action.id}
                  action={action}
                  block={block}
                  isDisabled={disabledState}
                />
              ))}
            {pinSlot}
            {isClosable && (
              <ArvoIconButton
                className={`${block}__close`}
                size="sm"
                variant="tertiary"
                icon="close"
                tooltip="Close"
                isDisabled={disabledState}
                onClick={() => { if (!disabledState) onClose?.(); }}
              />
            )}
          </div>
        </div>
      )}

      {/* Sticky region */}
      {stickyConfig && !loadingState && (
        <div className={`${block}__sticky`}>
          {stickyConfig.banner && (
            <div className={`${block}__banner`}>
              <ArvoBannerAlert
                type={stickyConfig.banner.type}
                title={stickyConfig.banner.title ?? undefined}
                message={stickyConfig.banner.message}
                isCompact={stickyConfig.banner.isCompact}
                isDismissible={stickyConfig.banner.isDismissible ?? false}
                onDismiss={stickyConfig.banner.onDismiss}
              />
            </div>
          )}
          {stickyConfig.tabs && stickyConfig.tabs.length > 0 && (
            <div className={`${block}__tabs`}>
              <ArvoTabstrip
                variant="primary"
                size="sm"
                tabs={tabsForTabstrip}
                selectedId={selectedTabId}
                isDisabled={disabledState}
                onSelect={(detail) => {
                  setSelectedTabId(detail.id);
                  onTabSelect?.(detail.id);
                }}
              />
            </div>
          )}
          {stickyConfig.search && (
            <div
              ref={searchRef}
              className={`${block}__search`}
              onKeyDown={(e) => {
                if (e.key !== 'ArrowDown') return;
                const firstItem = listRef.current?.querySelector<HTMLElement>(
                  `.${block}__item`,
                );
                if (firstItem) {
                  e.preventDefault();
                  firstItem.focus();
                  tabRovingRef.current?.setActiveItem(0);
                }
              }}
            >
              <ArvoSearch
                variant="filter"
                value={searchQuery}
                placeholder={searchPlaceholder}
                shortcut={searchShortcut}
                isFullWidth
                isDisabled={disabledState}
                counter={searchCounter}
                onSearch={handleSearchChange}
                onChange={handleSearchChange}
                onClear={handleClearSearch}
                aria-label={searchPlaceholder}
              />
            </div>
          )}
          {stickyConfig.info && infoMessage && (
            <PanelInfo
              config={stickyConfig.info}
              message={infoMessage}
              block={block}
            />
          )}
        </div>
      )}

      {/* Body */}
      <div className={`${block}__body`}>
        {loadingState ? (
          <SkeletonRows block={block} />
        ) : hasItems ? (
          emptyState ? (
            <EmptyState
              block={block}
              variant={emptyState}
              onClearSearch={emptyState === 'no-results' ? handleClearSearch : undefined}
            />
          ) : (
            <div
              ref={listRef}
              className={`${block}__list`}
              role={itemsRole}
              tabIndex={-1}
            >
              {filteredItems.map((item) => {
                // Cast to the optional default-item shape so we can read
                // isActive/isDisabled (and the leading slot fields used by
                // the default template). The PanelShellProps<T> generic
                // still constrains T to ListItemBase -- these reads are
                // structural (each field is optional and absent on plain
                // ListItemBase consumers).
                const defaultItem = item as unknown as ArvoPanelDefaultItem;
                const itemClasses = [
                  `${block}__item`,
                  defaultItem.isActive ? 'active' : '',
                  defaultItem.isDisabled ? 'is-disabled' : '',
                ]
                  .filter(Boolean)
                  .join(' ');
                const itemDisabled = !!defaultItem.isDisabled;
                return (
                  <div
                    key={getItemId(item)}
                    className={itemClasses}
                    data-item-id={getItemId(item)}
                    tabIndex={-1}
                    role="option"
                    aria-disabled={itemDisabled || undefined}
                    onClick={() => {
                      if (disabledState || itemDisabled) return;
                      onItemActivate?.(getItemId(item), item);
                    }}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' && !disabledState && !itemDisabled) {
                        e.preventDefault();
                        onItemActivate?.(getItemId(item), item);
                      }
                      if (e.key === 'ArrowUp') {
                        const itemEls = listRef.current?.querySelectorAll<HTMLElement>(`.${block}__item`);
                        if (itemEls) {
                          const idx = Array.from(itemEls).indexOf(e.currentTarget as HTMLElement);
                          if (idx === 0 && searchRef.current) {
                            e.preventDefault();
                            const input = searchRef.current.querySelector<HTMLElement>('input, textarea');
                            input?.focus();
                          }
                        }
                      }
                    }}
                  >
                    {renderItem
                      ? renderItem(item)
                      : renderDefaultItem(defaultItem, block)}
                  </div>
                );
              })}
            </div>
          )
        ) : (
          children
        )}
      </div>

      {/* Footer */}
      {!loadingState && actionsState && actionsState.length > 0 && (
        <div className={`${block}__footer`}>
          <div className={`${block}__footer-actions`}>
            {actionsState.map((action) => (
              // ArvoButton no longer accepts a tooltip prop (per the design
              // system tooltip standard). action.tooltip is preserved on the
              // ArvoPanelAction type for backward compat but ignored here --
              // consumers wrap the action with ArvoTooltip if needed.
              <ArvoButton
                key={action.id}
                data-action-id={action.id}
                data-icon-only={action.isIconOnly ? 'true' : undefined}
                size={action.size ?? 'md'}
                variant={action.variant ?? 'secondary'}
                label={action.label}
                icon={action.icon}
                isDisabled={(disabledState || action.isDisabled) || undefined}
                isLoading={action.isLoading}
                onClick={() => {
                  if (disabledState || action.isDisabled) return;
                  action.onClick?.();
                }}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export const PanelShell = forwardRef(PanelShellInner) as <T extends ListItemBase = ListItemBase>(
  props: PanelShellProps<T> & { ref?: React.Ref<PanelShellHandle> },
) => React.ReactElement | null;
